      "front": "하드웨어 인프라 진화의 핵심 정의는?",
      "back": "멀티코어 CPU, 분산 메모리, SSD/NVMe, 고속 네트워크, GPU/TPU 등으로 빅데이터 병렬 처리 기반이 바뀐 현상이다.",
