      "front": "클라우드·컨테이너·엣지의 핵심 정의는?",
      "back": "클라우드는 탄력적 자원과 관리형 서비스를, 컨테이너는 경량 격리·배포를, 엣지는 데이터 발생지 근처 저지연 처리를 제공한다.",
      "conceptId": "n34-C04",
      "fileId": "w3-infra",
